<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,post,state} from '../api'
const tab=ref('orders'),catalog=ref<any>({lines:[],stations:[],processes:[],products:[],orders:[],batches:[]}),rows=ref<any[]>([]),dialog=ref(false),form=ref<any>({}),editing=ref('')
const names:Record<string,string>={lines:'产线',stations:'工位',products:'产品',orders:'生产工单',batches:'生产批次',users:'用户与角色',grants:'工位授权',rules:'条码规则',audit:'操作审计'}
const fields:Record<string,string[]>={lines:['code','name','workshop'],stations:['code','name','lineId','processStepId'],products:['code','name'],orders:['code','productId','lineId','plan','status'],batches:['code','workOrderId','plan'],users:['account','name','role','password','active'],grants:['userId','stationId'],rules:['kind','prefixes','length','charset']}
const labels:Record<string,string>={code:'编码',name:'名称',workshop:'车间',lineId:'产线',processStepId:'工序',productId:'产品',plan:'计划数量',status:'状态',workOrderId:'工单',account:'账号',role:'角色',password:'密码',active:'启用',userId:'用户',stationId:'工位',kind:'条码类型',prefixes:'前缀（逗号分隔）',length:'总位数',charset:'字符类型'}
const users=ref<any[]>([])
function options(k:string):any[]{return ({lineId:catalog.value.lines,processStepId:catalog.value.processes,productId:catalog.value.products,workOrderId:catalog.value.orders,stationId:catalog.value.stations,userId:users.value,role:['Admin','Supervisor','Quality','Operator','TV'],status:['Open','Closed'],kind:['main','cell','sn','pack'],charset:['alnum','numeric','printable']} as any)[k]||[]}
function display(k:string,v:any){const opts=options(k);return opts.find((o:any)=>o.id===v)?.name||opts.find((o:any)=>o.id===v)?.code||(Array.isArray(v)?v.join(', '):v)}
async function load(){try{catalog.value=await api('/api/catalog');rows.value=await api('/api/admin/'+tab.value);if(state.user?.role==='Admin')users.value=await api('/api/admin/users')}catch(e:any){ElMessage.error(e.message)}}
function edit(row?:any){editing.value=row?.id||'';form.value=row?{...row}:{plan:100,status:'Open',role:'Operator',active:true,kind:'main',prefixes:'MC',length:14,charset:'alnum'};if(Array.isArray(form.value.prefixes))form.value.prefixes=form.value.prefixes.join(',');dialog.value=true}
async function save(){try{const body={...form.value};if(tab.value==='rules')body.prefixes=body.prefixes.split(',').map((s:string)=>s.trim()).filter(Boolean);if(editing.value)await api('/api/admin/'+tab.value+'/'+editing.value,{method:'PUT',body:JSON.stringify(body)});else await post('/api/admin/'+tab.value,body);dialog.value=false;await load();ElMessage.success('已保存')}catch(e:any){ElMessage.error(e.message)}}
async function remove(row:any){try{await ElMessageBox.confirm('确认删除？已有生产历史或关联的数据会被服务器拦截。','删除确认');await api('/api/admin/'+tab.value+'/'+row.id,{method:'DELETE'});await load()}catch(e:any){if(e?.message)ElMessage.error(e.message)}}
onMounted(load)
</script>
<template><aside class="sidebar"><div class="brand">生产协同工作台</div><nav class="nav"><button v-for="(name,key) in names" :key="key" :class="{active:tab===key}" @click="tab=key;load()">{{name}}</button></nav><div class="navfoot">数据库实时业务系统</div></aside><main class="main content"><div class="heading"><div><div class="eyebrow">MANUFACTURING EXECUTION</div><h1>{{names[tab]}}</h1><p class="sub">服务端校验 · 关联保护 · 操作留痕</p></div><el-button v-if="fields[tab]" type="primary" @click="edit()">＋ 新增{{names[tab]}}</el-button></div><section class="panel"><el-table :data="rows" stripe><el-table-column v-for="key in (fields[tab]||['at','action','outcome','detail']).filter(k=>k!=='password')" :key="key" :label="labels[key]||key" min-width="140"><template #default="{row}">{{display(key,row[key])}}</template></el-table-column><el-table-column v-if="fields[tab]" label="操作" width="160"><template #default="{row}"><el-button v-if="!['grants','rules'].includes(tab)" link @click="edit(row)">修改</el-button><el-button v-if="!['users','rules'].includes(tab)" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></section></main><el-dialog v-model="dialog" :title="names[tab]" width="580"><el-form label-width="110px"><el-form-item v-for="field in fields[tab]" :key="field" :label="labels[field]"><el-select v-if="options(field).length" v-model="form[field]"><el-option v-for="opt in options(field)" :key="opt.id||opt" :label="opt.name||opt.code||opt" :value="opt.id||opt"/></el-select><el-input-number v-else-if="['plan','length'].includes(field)" v-model="form[field]" :min="1"/><el-switch v-else-if="field==='active'" v-model="form[field]"/><el-input v-else v-model="form[field]" :type="field==='password'?'password':'text'"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
